/**
 * Per-topic scores of the trec_eval port against the reference implementations,
 * on the corner cases generated by scripts/make_fixtures.py (ties, graded and
 * negative labels, unjudged and unretrieved documents, rankings shorter and longer
 * than every cutoff, 1 to 60 relevant documents, non-ASCII document ids).
 */
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import { MEASURES } from '../src/core/measures.ts';
import { evaluateRun, formResRels, evaluateResRels, truncFusedMultiplyAdd } from '../src/core/trec-eval.ts';
import type { IprecRounding } from '../src/core/trec-eval.ts';
import { parseQrels, parseRun } from '../src/core/trec-format.ts';
import { fixtureJson, fixtureText, isClose, pytrecEvalRounding } from './helpers.ts';

type Scores = Record<string, Record<string, number>>;

const qrels = parseQrels(fixtureText('measures/qrels.txt')).qrels;
const run = parseRun(fixtureText('measures/run.txt')).run;

function compare(expected: Scores, rounding: IprecRounding, naming: 'id' | 'trecName'): void {
  const table = evaluateRun(run, qrels, { iprecRounding: rounding });
  const rows = new Map(table.topics.map((topic, t) => [topic, table.values[t] as Float64Array]));
  const errors: string[] = [];
  let exact = 0;
  let total = 0;
  for (const [topic, values] of Object.entries(expected)) {
    const row = rows.get(topic);
    assert.ok(row, `topic ${topic} missing from the port's output`);
    MEASURES.forEach((m, i) => {
      const want = values[m[naming]];
      assert.notEqual(want, undefined, `reference lacks ${m[naming]}`);
      const got = row[i] as number;
      total++;
      if (got === want) exact++;
      else if (!isClose(got, want as number, 1e-13, 1e-13)) errors.push(`${topic} ${m[naming]}: expected ${want}, got ${got}`);
    });
  }
  assert.ok(total > 6000, 'the fixture covers enough values');
  assert.deepEqual(errors, [], `${errors.length} of ${total} values differ`);
  // Everything except nDCG (libm vs JS log2) is expected to agree bit for bit.
  assert.ok(exact / total > 0.97, `only ${exact} of ${total} values are bit-identical`);
}

describe('trec_eval measures', () => {
  test('match pytrec_eval through ir_measures (what repro_eval computes), including unretrieved topics', () => {
    const reference = fixtureJson<{ scores: Scores; versions: { machine?: string } }>('measures-pytrec_eval.json');
    compare(reference.scores, pytrecEvalRounding(reference.versions), 'id');
    const table = evaluateRun(run, qrels);
    assert.deepEqual(table.topics, Object.keys(reference.scores).sort((a, b) => (a < b ? -1 : 1)));
  });

  test('match trec_eval 10.0 with lround-based iprec_at_recall', () => {
    const reference = fixtureJson<{ scores: Scores; generator: string }>('measures-trec_eval10.json');
    assert.match(reference.generator, /10\.0/);
    compare(reference.scores, 'v10', 'trecName');
  });

  test('the two iprec_at_recall roundings differ where they should', () => {
    // 7 relevant documents at ranks 1, 3, ..., 13: 0.2 * 7 = 1.4 → 2 (v9) or 1 (v10) relevant documents.
    const judgements = new Map<string, number>();
    const ranking: Array<{ docId: string; score: number }> = [];
    for (let i = 0; i < 7; i++) {
      judgements.set(`r${i}`, 1);
      judgements.set(`n${i}`, 0);
      ranking.push({ docId: `r${i}`, score: 100 - 2 * i }, { docId: `n${i}`, score: 99 - 2 * i });
    }
    const rr = formResRels(ranking, judgements);
    const at = (rounding: IprecRounding): number => evaluateResRels(rr, { iprecRounding: rounding })[MEASURES.findIndex((m) => m.id === 'IPrec@0.2')] as number;
    assert.equal(at('v9'), 2 / 3);
    assert.equal(at('v9-fma'), 2 / 3);
    assert.equal(at('v10'), 1);
  });

  test('a fused multiply-add rounds once', () => {
    // 0.7 · 3 + 0.9 is 2.9999999999999996 with two roundings but 3 with one.
    assert.equal(Math.trunc(0.7 * 3 + 0.9), 2);
    assert.equal(truncFusedMultiplyAdd(0.7, 3, 0.9), 3);
    assert.equal(truncFusedMultiplyAdd(0.3, 57, 0.9), 18);
    assert.equal(Math.trunc(0.3 * 57 + 0.9), 17);
    for (let n = 0; n <= 2000; n += 7) {
      for (const r of [0.0, 0.1, 0.5, 0.9, 1.0]) assert.equal(truncFusedMultiplyAdd(r, n, 0.9), Math.trunc(r * n + 0.9), `${r} · ${n}`);
    }
    assert.equal(truncFusedMultiplyAdd(2.5, 4, 0.25), 10);
    assert.equal(truncFusedMultiplyAdd(0, 0, 0.9), 0);
  });

  test('qrels topics without results score 0 and unjudged run topics are ignored', () => {
    const table = evaluateRun(run, qrels);
    assert.ok(table.missingTopics.includes('161'));
    assert.ok(table.ignoredTopics.includes('160'));
    const row = table.values[table.topics.indexOf('161')] as Float64Array;
    assert.ok(row.every((v) => v === 0));
  });

  test('relevance level changes what counts as relevant', () => {
    const judgements = new Map([
      ['a', 1],
      ['b', 2],
      ['c', 0],
    ]);
    const ranking = [
      { docId: 'a', score: 3 },
      { docId: 'b', score: 2 },
      { docId: 'c', score: 1 },
    ];
    const ap = MEASURES.findIndex((m) => m.id === 'AP');
    assert.equal(evaluateResRels(formResRels(ranking, judgements, 1))[ap], 1);
    assert.equal(evaluateResRels(formResRels(ranking, judgements, 2), { relevanceLevel: 2 })[ap], 0.5);
  });
});
